/**
 * An enumeration specifying the weight (boldness) of a font.
 */
enum PangoWeight: int
{
    case Thin = 100;
    case Ultralight = 200;
    case Light = 300;
    case Semilight = 350;
    case Book = 380;
    case Normal = 400;
    case Medium = 500;
    case Semibold = 600;
    case Bold = 700;
    case Ultrabold = 800;
    case Heavy = 900;
    case Ultraheavy = 1000;
}

/**
 * `PangoWrapMode` describes how to wrap the lines of a `PangoLayout` to the desired width.
 */
enum PangoWrapMode: int
{
    case Word = 0;
    case Char = 1;
    case WordChar = 2;
}
